
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbe_mod_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbe_mod", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.303466280309815e+00, -4.221751969801685e+00, -4.107360549181835e+00, -3.949130791513855e+00, -3.734007710269481e+00, -3.448713921081480e+00, -3.083626990487783e+00, -2.639601861100579e+00, -2.136182373237825e+00, -1.610341787816106e+00, -1.087330654140273e+00, -7.092152113058243e-01, -6.021128446143272e-01, -5.013193796223684e-01, -3.704453388856174e-01, -2.428197363551725e-01, -1.333543817874910e-01, -4.952125728142660e-02, -1.081192733711422e-02, -1.216202148889897e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


